"""Cue quality / hallucination heuristics (post-ASR filter)."""

from __future__ import annotations

import re
from typing import Any

# Same line / phrase repeated many times (classic Whisper loop)
_REPEAT_TOKEN = re.compile(r"(.{3,40}?)\1{3,}")
# Single-kana stutter spam: 「ててててて」「ああああ」
_STUTTER_KANA = re.compile(r"^([ぁ-んァ-ンー])\1{3,}[。．.!！?？、,\s~～]*$")

# Whole-cue YouTube / outro fillers Whisper often invents on soft JA AV audio.
# Keep conservative: do NOT include bare 「ありがとうございました」 (real dialogue).
_HALLUCINATION_EXACT: frozenset[str] = frozenset(
    {
        # ZH / generic
        "完毕",
        "结束",
        "完",
        "谢谢观看",
        "感谢观看",
        "请订阅",
        "字幕by",
        "请使用简体中文输出。",
        "请使用简体中文输出",
        "請使用繁體中文輸出。",
        "請使用繁體中文輸出",
        "简体中文",
        "繁体中文",
        "繁體中文",
        "字幕：",
        "subtitles by",
        "thanks for watching",
        "thank you for watching",
        "the end",
        # JA YouTube / soft-scene fillers (validated on FNS-235 AV debug)
        "ご視聴ありがとうございました",
        "ご視聴頂きありがとうございます",
        "ご視聴いただきありがとうございます",
        "ご清聴ありがとうございました",
        "チャンネル登録よろしくお願いします",
        "チャンネル登録お願いいたします",
        "高評価よろしくお願いします",
        "グッドボタンよろしくお願いします",
        "お疲れ様でした",
        "お疲れさまでした",
        "おめでとうございます",
        "それではまた",
        "次回もお楽しみに",
        "バイバイ",
        "ばいばい",
        "Bye-bye",
        "bye-bye",
        "BYE-BYE",
        # Soft-AV logo / chapter hallucinations (HMN-878)
        "本集",
        "本集。",
        "寂寞",
        "寂寞酷",
        "寂寞曲",
        "寂寞笑",
        "好厉害",
        "准备",
        # Opening BGM / logo echoes (IPZZ-745)
        "おわり",
        "おわり。",
        "終わり",
        "終わり。",
        "ユーモア",
        "ユーモア。",
        "the end.",
        "The End",
        "THE END",
    }
)

_HALLUCINATION_RE = re.compile(
    r"^(?:"
    r"[Oo○〇◯●]{2,}|"
    r"[・･\.。…]{1,}|"
    r"[♪♫♩♬◆◇■□★☆●○◎※]+|"
    r"字幕\s*[:：by].*|"
    r"thanks?\s+for\s+watching.*|"
    r"ご視聴.*ありがとう.*|"
    r"チャンネル登録.*|"
    r"高評価.*|"
    r"グッドボタン.*"
    r")$",
    re.IGNORECASE,
)

_SYMBOL_ONLY_CUE = re.compile(
    r"^[♪♫♩♬·.•…\-—_~～。．.!！?？、,，\s◆◇■□★☆●○◎※]+$"
)
_BPE_ONLY = re.compile(r"^[\u2581\s]+$")


def _normalize_text(text: str) -> str:
    return re.sub(r"\s+", "", str(text or "")).strip().lower()


def is_phrase_hallucination(text: str) -> bool:
    """True when the whole cue matches a known YouTube / filler hallucination phrase."""
    raw = str(text or "").strip()
    if not raw:
        return False
    if raw in _HALLUCINATION_EXACT or raw.lower() in _HALLUCINATION_EXACT:
        return True
    return bool(_HALLUCINATION_RE.match(raw))


# Bare politeness lines Whisper invents on soft JA AV (FNS-235). Keep longer
# real dialogue; only drop short whole-cue hits.
_SHORT_SOFT_FILLERS: frozenset[str] = frozenset(
    {
        "ありがとうございました",
        "ありがとうございます",
        "ありがとう",
        "失礼します",
        "失礼いたしました",
        "よろしくお願いします",
        "お願いいたします",
    }
)
_SHORT_SOFT_FILLER_MAX_S = 1.35
# Absurd speaking rate ⇒ decoder garbage
_MAX_CPS_JA = 28.0
_MAX_CPS_GENERIC = 36.0
_NVV_ONLY = re.compile(
    r"^[あぁアァいぃイィうぅウゥえぇエェおぉオォんンー〜～っッ"
    r"・･\.。…、,！!？?\s♡♥❤]+$"
)


def _char_count(text: str) -> int:
    return len(re.sub(r"\s+", "", str(text or "")))


def _is_ja_heavy(text: str) -> bool:
    raw = re.sub(r"\s+", "", str(text or ""))
    if not raw:
        return False
    ja = sum(
        1
        for ch in raw
        if "\u3040" <= ch <= "\u30ff" or "\u4e00" <= ch <= "\u9fff"
    )
    return (ja / max(len(raw), 1)) >= 0.35


def _is_pure_nvv(text: str) -> bool:
    """True for extreme moan/spam runs only (keep medium soft-scene NVV)."""
    raw = str(text or "").strip()
    if not raw or not _NVV_ONLY.match(raw):
        return False
    bare = re.sub(r"[。．.!！?？、,\s…・･]+", "", raw)
    # ≥18 pure moan glyphs ≈ stuck decoder; shorter あっ/んっ lines are dialogue.
    return len(bare) >= 18


def is_hallucinated_cue(
    cue: dict[str, Any],
    *,
    max_duration_s: float = 45.0,
    ja_av: bool = False,
) -> bool:
    """
    True when a cue looks like a loop / stuck decoder output / known filler phrase.

    Conservative: only flag strong signals so real dialogue is kept.
    ``ja_av=True`` enables Japanese adult-video soft-scene heuristics (FNS-235).
    """
    text = str(cue.get("text") or "").strip()
    if not text:
        return True
    if _SYMBOL_ONLY_CUE.match(text) or _BPE_ONLY.match(text):
        return True
    if is_phrase_hallucination(text):
        return True
    start = float(cue.get("start") or 0)
    end = float(cue.get("end") or start)
    dur = max(0.0, end - start)
    if dur > max_duration_s and len(text) < 12:
        return True
    if dur <= _SHORT_SOFT_FILLER_MAX_S:
        bare = _normalize_text(text).rstrip("。．.!！?")
        if bare in _SHORT_SOFT_FILLERS:
            return True
    if _REPEAT_TOKEN.search(text):
        return True
    # Single-kana stutter: 「ててててて。」 (decoder stuck on soft speech)
    # Soft AV keeps shorter ああ… / んん… as dialogue; only drop long spam.
    stutter_text = text.replace(" ", "")
    if ja_av:
        if re.match(r"^([ぁ-んァ-ンー])\1{7,}[。．.!！?？、,\s~～]*$", stutter_text):
            return True
    elif _STUTTER_KANA.match(stutter_text):
        return True
    # Character-level repetition: "あああああ…" style spam
    # Soft-scene moans often look like this — only drop extreme runs.
    spam_min = 18 if ja_av else 12
    if len(text) >= spam_min:
        uniq = len(set(text.replace(" ", "")))
        if uniq <= 2:
            return True
    if ja_av:
        if _is_pure_nvv(text):
            return True
        # Impossible CPS on JA softsubs (threshold ~28–30).
        # Extreme CPS (≫80) is almost always collapsed timestamps (anime-whisper
        # emits ~30s of speech as a 0.3–0.9s span) — do not delete real dialogue;
        # whisper_fw.repair_collapsed_asr_cues should have fixed these already.
        n = _char_count(text)
        if dur > 0.05 and n >= 4:
            cps = n / dur
            if cps > 80.0:
                return False
            limit = _MAX_CPS_JA if _is_ja_heavy(text) else _MAX_CPS_GENERIC
            if cps > limit:
                return True
        # Soft-scene English leak / kana garble
        if re.search(r"[A-Za-z]{4,}", text) and (
            re.search(r"(ェェ|ヴェ|ヴ|mainly|subscribe|watching)", text, re.I)
            or (
                sum(1 for ch in text if ch.isascii() and ch.isalpha())
                >= sum(1 for ch in text if "\u3040" <= ch <= "\u30ff")
            )
        ):
            return True
    return False


def find_duplicate_streaks(
    cues: list[dict[str, Any]],
    *,
    min_streak: int = 4,
    ja_av: bool = False,
) -> set[int]:
    """Indices of cues that repeat the same normalized text in a long streak."""
    drop: set[int] = set()
    if not cues:
        return drop
    i = 0
    while i < len(cues):
        norm = _normalize_text(str(cues[i].get("text") or ""))
        j = i + 1
        while j < len(cues) and _normalize_text(str(cues[j].get("text") or "")) == norm:
            j += 1
        streak = j - i
        # JA AV: short reactive lines loop easily — drop adjacent dups (streak≥2).
        # Medium lines: collapse 3+ identical.
        need = min_streak
        if ja_av and norm:
            nlen = len(norm)
            if nlen <= 6:
                need = 2
            else:
                need = min(min_streak, 3)
        if norm and streak >= need:
            # Keep first, drop the rest of the streak
            for k in range(i + 1, j):
                drop.add(k)
        i = j
    return drop


def filter_hallucinated_cues(
    cues: list[dict[str, Any]] | None,
    *,
    max_duration_s: float = 45.0,
    min_streak: int = 4,
    ja_av: bool = False,
) -> tuple[list[dict[str, Any]], int]:
    """
    Drop hallucinated / looped cues.

    Returns (cleaned_cues, dropped_count).
    """
    if not cues:
        return [], 0
    streak_drop = find_duplicate_streaks(cues, min_streak=min_streak, ja_av=ja_av)
    out: list[dict[str, Any]] = []
    dropped = 0
    for i, cue in enumerate(cues):
        if i in streak_drop or is_hallucinated_cue(
            cue, max_duration_s=max_duration_s, ja_av=ja_av
        ):
            dropped += 1
            continue
        out.append(cue)
    return out, dropped


def filter_low_confidence_cues(
    cues: list[dict[str, Any]] | None,
    *,
    min_avg_logprob: float = -1.05,
    max_no_speech_prob: float = 0.65,
    ja_av: bool = False,
    film: bool = False,
) -> tuple[list[dict[str, Any]], int]:
    """
    Drop Whisper cues that carry weak confidence metadata.

    Cues without avgLogprob / noSpeechProb are kept (SenseVoice path).
    ``ja_av`` slightly tightens thresholds (soft scenes invent confident fillers less
    often than low-prob loops).
    ``film`` tightens against music-bed punctuation hallucinations.
    """
    if not cues:
        return [], 0
    min_lp = float(min_avg_logprob)
    max_nsp = float(max_no_speech_prob)
    if ja_av:
        # Soft dialogue / moans often have weak logprob + high no_speech —
        # raise tolerance so breathy lines survive (comment previously mismatched code).
        min_lp = min(min_lp, -1.45)
        max_nsp = max(max_nsp, 0.88)
    elif film:
        min_lp = max(min_lp, -0.95)
        max_nsp = min(max_nsp, 0.55)
    out: list[dict[str, Any]] = []
    dropped = 0
    for cue in cues:
        has_meta = False
        bad = False
        if cue.get("avgLogprob") is not None:
            has_meta = True
            try:
                if float(cue["avgLogprob"]) < min_lp:
                    bad = True
            except (TypeError, ValueError):
                pass
        if cue.get("noSpeechProb") is not None:
            has_meta = True
            try:
                if float(cue["noSpeechProb"]) > max_nsp:
                    bad = True
            except (TypeError, ValueError):
                pass
        if has_meta and bad:
            dropped += 1
            continue
        out.append(cue)
    return out, dropped


def merge_timeline_cues(
    cues: list[dict[str, Any]] | None,
    *,
    max_gap_s: float = 0.35,
    max_merged_duration_s: float = 8.0,
) -> list[dict[str, Any]]:
    """
    Merge overlapping or nearly-adjacent cues with identical / nested text.

    Helps after clip re-transcription leaves duplicate fragments.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict)),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    merged: list[dict[str, Any]] = [ordered[0]]
    for cue in ordered[1:]:
        prev = merged[-1]
        p0 = float(prev.get("start") or 0)
        p1 = float(prev.get("end") or p0)
        c0 = float(cue.get("start") or 0)
        c1 = float(cue.get("end") or c0)
        pt = _normalize_text(str(prev.get("text") or ""))
        ct = _normalize_text(str(cue.get("text") or ""))
        overlap = c0 <= p1 + max_gap_s
        same_or_nested = bool(pt and ct) and (pt == ct or pt in ct or ct in pt)
        if overlap and same_or_nested and (max(p1, c1) - min(p0, c0)) <= max_merged_duration_s:
            # Keep the longer text
            prev_text = str(prev.get("text") or "")
            cue_text = str(cue.get("text") or "")
            text = cue_text if len(cue_text) >= len(prev_text) else prev_text
            merged[-1] = {
                **prev,
                "start": min(p0, c0),
                "end": max(p1, c1),
                "text": text,
            }
        elif overlap and c0 < p1 and not same_or_nested:
            # Soft overlap of different lines: clamp previous end
            if c0 > p0 + 0.2:
                prev["end"] = max(p0 + 0.2, min(p1, c0 - 0.02))
            merged.append(cue)
        else:
            merged.append(cue)
    return merged


_SHORT_PARTICLE = re.compile(
    r"^(?:"
    r"ねえ|ねぇ|ね|うん+|ええ+|あっ?|ああ+|う+|ん+|えー+|あー+|うーん+"
    r"|いや|えっ|えっと|じゃあ|じゃ|と、+|で、+|が、+|を、+|も、+"
    r"|はい|うん|ふぅ|はぁ|ほっ"
    r")[。.!！?？、,\s~～ー]*$",
)

_EN_SHORT_FRAGMENTS = frozenset(
    {
        "a", "an", "the", "to", "of", "and", "or", "but", "with", "for", "in", "on",
        "at", "by", "from", "as", "is", "are", "was", "were", "be", "been", "am",
        "i", "we", "you", "he", "she", "they", "it", "my", "your", "our", "their",
        "again", "only", "just", "so", "no", "yes", "oh", "uh", "um", "ok", "okay",
        "this", "that", "then", "than", "if", "when", "who", "what", "how",
    }
)


def _cue_is_short_fragment(text: str) -> bool:
    """True for particles / stubs that should attach to a neighbor before MT."""
    s = str(text or "").strip()
    if not s:
        return True
    # Strip common ASR hyphen prefix
    s = re.sub(r"^[\-\–—−‐]+", "", s).strip()
    if not s:
        return True
    if len(s) <= 2:
        return True
    if _SHORT_PARTICLE.match(s):
        return True
    # Trailing incomplete conjunction
    if len(s) <= 6 and s.endswith(("と、", "で、", "が、", "を、", "て、", "、")):
        return True
    # English dangling / stub words (Spider-Verse style micro-cuts)
    en_bare = re.sub(r"[^A-Za-z']+", "", s).lower()
    if en_bare in _EN_SHORT_FRAGMENTS:
        return True
    words = re.findall(r"[A-Za-z']+", s)
    if words and len(words) <= 2 and len(s) <= 14 and _cue_looks_incomplete(s):
        if words[-1].lower() in _EN_SHORT_FRAGMENTS:
            return True
    return False


def _cue_looks_incomplete(text: str) -> bool:
    """True when a cue likely continues into the next (no sentence-final punct)."""
    s = str(text or "").strip()
    if not s:
        return True
    if re.search(r"[。！？!?…」』]$", s):
        return False
    # Latin sentence end
    if re.search(r"[.!?]$", s):
        return False
    return True


# Known mid-cut joins (Whisper often splits these across a pause / clip boundary).
# (prev_suffix, cur_prefix, max_gap_s)
_CLAUSE_JOINS: tuple[tuple[str, str, float], ...] = (
    ("確", "かに", 6.0),
    ("確", "かで", 6.0),
    ("思っ", "たら", 3.5),
    ("でしょ", "うか", 3.5),
    ("でしょう", "か", 3.5),
    ("近", "くに", 1.5),
    ("近", "くあ", 1.5),
)


def _clause_join_gap(prev: str, cur: str) -> float | None:
    """Return allowed gap (seconds) when prev|cur is a known clause cut, else None."""
    pt = str(prev or "").strip()
    ct = str(cur or "").strip()
    if not pt or not ct:
        return None
    for left, right, gap in _CLAUSE_JOINS:
        if pt.endswith(left) and ct.startswith(right):
            return gap
    return None


def merge_short_neighbor_cues(
    cues: list[dict[str, Any]] | None,
    *,
    max_gap_s: float = 0.55,
    max_merged_duration_s: float = 7.0,
) -> list[dict[str, Any]]:
    """
    Merge tiny / particle cues into neighbors so Opus sees fuller phrases.

    Example: 「じゃあ」+「つきます。」→「じゃあ、つきます。」 when gap is small.
    Also glues mid-word splits: 「すごく近」+「くにある。」 (whisper-ja cut)
    and known clause cuts: 「…でしょうか確」+「かにずっと」 (indeed).
    Does not merge two long sentences.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict)),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []

    def _join(a: str, b: str) -> str:
        left = str(a or "").strip()
        right = str(b or "").strip()
        if not left:
            return right
        if not right:
            return left
        # Avoid double punctuation when gluing
        if left.endswith(("、", ",", "，")) or right.startswith(("、", ",", "，")):
            return f"{left}{right}"
        if re.search(r"[\u3040-\u30ff\u4e00-\u9fff]$", left) and re.search(
            r"^[\u3040-\u30ff\u4e00-\u9fff]", right
        ):
            return f"{left}{right}"
        return f"{left} {right}".strip()

    merged: list[dict[str, Any]] = [ordered[0]]
    for cue in ordered[1:]:
        prev = merged[-1]
        p0 = float(prev.get("start") or 0)
        p1 = float(prev.get("end") or p0)
        c0 = float(cue.get("start") or 0)
        c1 = float(cue.get("end") or c0)
        gap = c0 - p1
        pt = str(prev.get("text") or "")
        ct = str(cue.get("text") or "")
        dur = max(p1, c1) - min(p0, c0)
        short_prev = _cue_is_short_fragment(pt)
        short_cur = _cue_is_short_fragment(ct)
        ct_bare = ct.strip()
        # Mid-cut continuation: prev has no 。！？ and next is a short stub
        cont_cut = (
            gap <= max(0.45, max_gap_s)
            and dur <= max(max_merged_duration_s, 8.0)
            and _cue_looks_incomplete(pt)
            and len(ct_bare) <= 18
            and not (len(pt) >= 28 and len(ct_bare) >= 14)
        )
        join_gap = _clause_join_gap(pt, ct)
        clause_cut = (
            join_gap is not None
            and gap <= join_gap
            and dur <= max(max_merged_duration_s, 12.0)
        )
        can = (
            gap <= max_gap_s
            and dur <= max_merged_duration_s
            and (short_prev or short_cur)
            and not (len(pt) >= 10 and len(ct) >= 10)
        ) or cont_cut or clause_cut
        if can:
            merged[-1] = {
                **prev,
                "start": min(p0, c0),
                "end": max(p1, c1),
                "text": _join(pt, ct),
            }
        else:
            merged.append(cue)
    return merged
